package vn.com.apartment.billing;
import jakarta.persistence.*;import java.time.LocalDateTime;import vn.com.apartment.resident.Customer;
@Entity @Table(name="payment_notifications") public class PaymentNotification{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="payment_qr_request_id") private PaymentQrRequest qrRequest;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_id") private Customer customer;@Column(nullable=false,length=20) private String channel;@Column(nullable=false,length=150) private String recipient;@Column(nullable=false,length=20) private String status;@Column(name="provider_message_id",length=150) private String providerMessageId;@Column(name="error_message",length=500) private String errorMessage;@Column(name="sent_at") private LocalDateTime sentAt;@Column(name="created_at",nullable=false) private LocalDateTime createdAt=LocalDateTime.now();protected PaymentNotification(){}public PaymentNotification(PaymentQrRequest qr,Customer customer,String channel,String recipient){qrRequest=qr;this.customer=customer;this.channel=channel;this.recipient=recipient;status="PENDING";}public void sent(){status="SENT";sentAt=LocalDateTime.now();}public void failed(String error){status="FAILED";errorMessage=error==null?"Không gửi được thông báo.":error.substring(0,Math.min(500,error.length()));}public String getStatus(){return status;}public String getChannel(){return channel;}}
